.eco-heading { display:flex; align-items:flex-start; justify-content:space-between; gap:18px; margin-bottom:22px; }
.eco-heading h2 { font-size:23px; letter-spacing:-.025em; margin:0 0 7px; }
.eco-heading p,.eco-muted { color:var(--rd-secondary); font-size:12px; line-height:1.6; margin:0; }
.eco-actions { display:flex; flex-wrap:wrap; align-items:center; gap:8px; }
.eco-actions button,.eco-button { border:1px solid var(--rd-line); background:var(--rd-list); border-radius:6px; padding:7px 11px; color:var(--rd-text); font:inherit; font-size:12px; }
.eco-actions button:hover,.eco-button:hover { background:var(--rd-hover); }
.eco-actions button:disabled,.eco-button:disabled { opacity:.45; cursor:default; }
.eco-primary { background:var(--rd-blue)!important; color:white!important; border-color:var(--rd-blue)!important; }
.eco-field[hidden] { display:none; }
.eco-list { border-top:1px solid var(--rd-line); }
.eco-row { display:flex; align-items:center; gap:14px; border:0; border-bottom:1px solid var(--rd-line-soft); width:100%; background:transparent; color:var(--rd-text); padding:17px 4px; text-align:left; }
.eco-row:hover { background:var(--rd-hover); }
.eco-row>span { min-width:0; flex:1; }
.eco-row strong { display:block; font-size:14px; font-weight:500; overflow-wrap:anywhere; }
.eco-row small { display:block; margin-top:5px; color:var(--rd-secondary); font-size:12px; line-height:1.5; overflow-wrap:anywhere; }
.eco-row time { font-size:11px; color:var(--rd-tertiary); white-space:nowrap; }
.eco-empty { display:grid; justify-items:start; gap:13px; padding:36px 0; max-width:460px; }
.eco-empty h3 { margin:0; font-size:18px; font-weight:500; }
.eco-empty p { margin:0; color:var(--rd-secondary); font-size:13px; line-height:1.7; }
.eco-back { border:0; background:transparent; color:var(--rd-blue); padding:0 0 18px; font-size:12px; }
.eco-question { font-size:14px; line-height:1.8; white-space:pre-wrap; border-bottom:1px solid var(--rd-line); padding:0 0 20px; margin:0 0 20px; overflow-wrap:anywhere; }
.eco-message { border-bottom:1px solid var(--rd-line-soft); padding:16px 0 23px; }
.eco-message header { display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:13px; font-size:12px; }
.eco-message header strong { font-weight:600; }
.eco-message header small { color:var(--rd-secondary); font-size:11px; }
.eco-message h4 { color:var(--rd-secondary); margin:16px 0 5px; font-size:11px; font-weight:500; }
.eco-message p { margin:0; font-size:13px; line-height:1.8; white-space:pre-wrap; overflow-wrap:anywhere; }
.eco-comparison { display:grid; grid-template-columns:repeat(auto-fit,minmax(220px,1fr)); gap:16px; }
.eco-comparison .eco-message { align-self:start; }
.eco-inspector h2 { font-size:21px; letter-spacing:-.02em; margin:12px 0; overflow-wrap:anywhere; }
.eco-inspector section { border-top:1px solid var(--rd-line); margin-top:22px; padding-top:17px; }
.eco-inspector h3 { font-size:11px; color:var(--rd-secondary); font-weight:500; margin:0 0 12px; }
.eco-inspector p { font-size:12px; line-height:1.7; white-space:pre-wrap; overflow-wrap:anywhere; }
.eco-inspector dl { display:grid; grid-template-columns:75px 1fr; gap:11px; font-size:12px; }
.eco-inspector dt { color:var(--rd-secondary); }
.eco-inspector dd { margin:0; overflow-wrap:anywhere; }
.eco-inspector .eco-actions { margin-top:14px; }
.eco-role { margin:0 0 13px; padding:0 0 13px; border-bottom:1px solid var(--rd-line-soft); }
.eco-role strong { display:block; font-size:12px; font-weight:500; }
.eco-role small { display:block; margin-top:4px; color:var(--rd-secondary); font-size:11px; overflow-wrap:anywhere; }
.eco-notice { border-left:2px solid var(--rd-orange); margin:14px 0; padding:3px 0 3px 12px; color:var(--rd-secondary); font-size:12px; line-height:1.7; }
.eco-diff { display:grid; gap:18px; }
.eco-diff h3 { font-size:12px; font-weight:500; margin:0 0 8px; }
.eco-diff pre,.eco-context { font-size:12px; font-family:inherit; line-height:1.7; white-space:pre-wrap; overflow-wrap:anywhere; margin:0; color:var(--rd-secondary); }
.eco-dialog { width:min(590px,calc(100vw - 40px)); max-height:85vh; overflow:auto; box-sizing:border-box; border:1px solid var(--rd-line); border-radius:12px; background:var(--rd-bg); color:var(--rd-text); padding:26px; box-shadow:0 20px 70px rgba(0,0,0,.16); }
.eco-dialog::backdrop { background:rgba(0,0,0,.22); }
.eco-dialog h2 { margin:0 0 18px; font-size:21px; }
.eco-dialog form { display:grid; gap:16px; }
.eco-field { display:grid; gap:7px; font-size:12px; }
.eco-field input,.eco-field textarea,.eco-field select { box-sizing:border-box; width:100%; min-width:0; padding:9px 11px; border:1px solid var(--rd-line); border-radius:6px; background:var(--rd-list); color:var(--rd-text); font:inherit; font-size:13px; }
.eco-field textarea { min-height:105px; line-height:1.6; resize:vertical; }
.eco-field small { color:var(--rd-secondary); font-size:11px; line-height:1.6; }
.eco-field-pair { display:grid; grid-template-columns:1fr 1fr; gap:16px; }
.eco-checks { display:grid; gap:10px; margin:0; border:1px solid var(--rd-line); border-radius:6px; padding:12px; }
.eco-check { display:flex; align-items:flex-start; gap:9px; font-size:12px; line-height:1.6; }
.eco-check input { margin-top:4px; }
.eco-form-error { color:var(--rd-orange); font-size:12px; line-height:1.6; }
.eco-search { width:100%; box-sizing:border-box; margin-bottom:15px; border:1px solid var(--rd-line); border-radius:6px; padding:8px 10px; background:var(--rd-list); color:var(--rd-text); font-size:12px; }
@media(max-width:650px) { .eco-heading{flex-direction:column}.eco-field-pair{grid-template-columns:1fr}.eco-row time{display:none}.eco-comparison{grid-template-columns:1fr} }
/* Review and observation use the same restrained reading surface. */
.review-brief section,.observation-coverage{padding:18px 0;border-bottom:1px solid var(--line,#e4e4e7)}
.review-brief p,.review-citation p{white-space:pre-wrap;line-height:1.7}
.review-citation{margin:12px 0;padding:12px;border:1px solid var(--line,#e4e4e7);border-radius:10px}
.review-citation small{display:block;margin-bottom:8px}
.review-materials{margin-top:24px}.review-materials pre{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7;font-size:12px}
.review-highlight{background:#f8e7a4;color:#202020}
.observation-coverage{background:var(--surface,#fafafa);padding:16px;border-radius:12px;margin:12px 0}

