/* Frontend v2: quiet native panes, compact people, and one clear next action.
   Keep consent and real member readiness visible; decoration never implies activity. */
body[data-app] {font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang SC","Microsoft YaHei",sans-serif;-webkit-font-smoothing:antialiased}
body[data-app] :is(button,input,select,textarea){font-family:inherit}
body[data-app] :is(button,a,summary){-webkit-tap-highlight-color:transparent}
body[data-app] :is(.chat-header-actions button,.chat-member-add button,.chat-list-tools button){box-shadow:none;border-color:var(--eco-line);background:var(--eco-subtle);color:var(--eco-text)}
body[data-app] :is(.chat-list-tools,.chat-list,.radar-source-pane){background:var(--eco-subtle)}
body[data-app] :is(.chat-list-tools input,.radar-search){color:var(--eco-text);background:var(--eco-surface);border:1px solid var(--eco-line)}
body[data-app] :is(input,textarea)::placeholder{color:var(--eco-muted);opacity:1}
body[data-app] :is(.chat-header,.chat-member-strip,.chat-list,.radar-source-pane,.radar-discovery-pane){border-color:var(--eco-line)}
.yanxu-chat-focus .chat-layout{grid-template-columns:256px minmax(0,1fr)}
